(s1, s2, virus) = [input().strip() for _ in range(3)]
(n, m, v) = (len(s1), len(s2), len(virus))
next_suffix = [v for i in range(v)]
for i in range(v - 2, -1, -1):
	j = next_suffix[i + 1]
	while j <= v - 1 and virus[j] != virus[i + 1]:
		j = next_suffix[j]
	next_suffix[i] = j - 1

def memoize(function):
	memo = dict()

	def memoized(*args):
		if args in memo:
			return memo[args]
		ans = function(*args)
		memo[args] = ans
		return ans
	return memoized

@memoize
def lcs(i, j, k):
	if k < 0:
		return (float('-inf'), '')
	if i < 0 or j < 0:
		return (0, '')
	if s1[i] == s2[j]:
		if s1[i] != virus[k]:
			newk = k
			while newk < v and virus[newk] != s1[i]:
				newk = next_suffix[newk]
			r = lcs(i - 1, j - 1, newk - 1)
			return (r[0] + 1, r[1] + s1[i])
		else:
			r1 = lcs(i - 1, j - 1, k - 1)
			r1 = (r1[0] + 1, r1[1] + s1[i])
			r2 = lcs(i - 1, j - 1, k)
			return max(r1, r2, key=lambda x: x[0])
	return max(lcs(i, j - 1, k), lcs(i - 1, j, k), key=lambda x: x[0])
ans = lcs(n - 1, m - 1, v - 1)
if ans[0] > 0:
	print(ans[1])
else:
	print(0)
